/* Level overlay code after math/interpolation; generated by `decomp overlays stubs`, stubs replaced by C as functions are matched. */
#include "types.h"
#include "asm.h"

#define NOT_SDA

#define MACRO_ADDR

/* Apply three optional state changes to live mobys of one class. */
/* Ported from rac1-decomp (src/overlays/l17/mobyutil_00254B40.c: func_L17_00254B40), where it is exact; names translated to the US level program. */

typedef struct {
    char pad0[0x10];
    int value;
} Level17MobyLink;

typedef struct {
    char pad0[0x20];
    signed char state;
    char pad21[3];
    Level17MobyLink *link;
    char pad28[9];
    unsigned char active;
    char pad32[2];
    unsigned short flags;
    char pad36[0x5E];
    int linked_value;
    char pad98[0xE];
    short class_id;
    char padA8[0x58];
} Level17Moby;

extern Level17Moby *D_L17_0015FFD8;
extern Level17Moby *D_L17_0015FFE0;

void FUN_L17_00253a90(int class_id, int flag2, int flag1, int link_mode) {
    Level17Moby *moby;
    for (moby = D_L17_0015FFD8; moby <= D_L17_0015FFE0; moby++) {
        if (moby->class_id == class_id && moby->state >= 0) {
            if (flag2 != -1) {
                if (flag2 != 0)
                    moby->flags &= ~2;
                else
                    moby->flags |= 2;
            }
            if (flag1 != -1) {
                if (flag1 != 0) {
                    moby->active = 1;
                    moby->flags &= ~1;
                } else {
                    moby->active = 0;
                    moby->flags |= 1;
                }
            }
            if (link_mode != -1) {
                if (link_mode != 0)
                    moby->linked_value = moby->link->value;
                else
                    moby->linked_value = 0;
            }
        }
    }
}
